443	// Multi-tensor fused reduce + step: accumulate d_lr across all tensors,
444	// then apply the Prodigy update to each.
445	void launch_multi_tensor_prodigy_fused_reduce_step(
446	    std::vector<torch::Tensor>& params,
447	    std::vector<torch::Tensor>& grads,
448	    std::vector<torch::Tensor>& param_inits,
449	    std::vector<torch::Tensor>& exp_avgs,
450	    std::vector<torch::Tensor>& exp_avg_sqs,
451	    std::vector<torch::Tensor>& s_bufs,
452	    std::vector<float>& bc1s, std::vector<float>& bc2s,
453	    torch::Tensor d_lr_buf,
454	    float beta1, float beta2, float lr, float wd, float eps
455	) {
456	    if (params.empty()) return;
457	    auto dev = params[0].device();
458	    auto r_partial = torch::zeros({1},
459	        torch::TensorOptions().device(dev).dtype(torch::kFloat32));
